-- Сумрак 2096: «Проект Мекка» (карта государств) в общей базе Supabase.
-- Запустить один раз: Supabase → SQL Editor → вставить целиком → Run. Повторный запуск безопасен.
-- Читать данные может любой (приложение игрока, веб-версия карты).
-- Писать — только через функции ниже, по логину и паролю редактора (в базе хранится только хэш пароля).

create table if not exists public.mecca_docs (
  coll       text        not null check (coll ~ '^[a-z_]{1,40}$'),
  id         text        not null check (length(id) between 1 and 200),
  data       jsonb       not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  primary key (coll, id)
);
alter table public.mecca_docs enable row level security;
alter table public.mecca_docs replica identity full;

drop policy if exists mecca_read on public.mecca_docs;
create policy mecca_read on public.mecca_docs for select to anon, authenticated using (true);
revoke insert, update, delete on public.mecca_docs from anon, authenticated;
grant select on public.mecca_docs to anon, authenticated;

-- Редакторы. Политик нет — таблицу не видит никто, кроме функций.
create table if not exists public.mecca_editors (
  login     text primary key,          -- в нижнем регистре
  pass_hash text not null              -- sha256('mecca|' || login || '|' || пароль)
);
alter table public.mecca_editors enable row level security;
revoke all on public.mecca_editors from anon, authenticated;

-- Логин Life, пароль RolevkaEremina (сам пароль здесь не записан, только его хэш).
insert into public.mecca_editors(login, pass_hash)
values ('life', 'bd4a514fbd59f27d05891fd52b33ff426a2bf5767a211c70a215b065065b3a84')
on conflict (login) do update set pass_hash = excluded.pass_hash;

create or replace function public.mecca_check(p_login text, p_pass text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists(
    select 1 from mecca_editors
    where login = lower(trim(coalesce(p_login, '')))
      and pass_hash = encode(sha256(convert_to('mecca|' || lower(trim(coalesce(p_login, ''))) || '|' || coalesce(p_pass, ''), 'UTF8')), 'hex'));
$$;

create or replace function public.mecca_login(p_login text, p_pass text) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  if not mecca_check(p_login, p_pass) then
    perform pg_sleep(1);              -- притормаживаем подбор пароля
    return false;
  end if;
  return true;
end $$;

create or replace function public.mecca_put(p_login text, p_pass text, p_coll text, p_id text, p_data jsonb)
returns timestamptz language plpgsql security definer set search_path = public as $$
declare t timestamptz := now();
begin
  if not mecca_check(p_login, p_pass) then raise exception 'mecca: access denied'; end if;
  if octet_length(p_data::text) > 1500000 then raise exception 'mecca: document too big'; end if;
  insert into mecca_docs(coll, id, data, updated_at) values (p_coll, p_id, coalesce(p_data, '{}'::jsonb), t)
  on conflict (coll, id) do update set data = excluded.data, updated_at = excluded.updated_at;
  return t;
end $$;

create or replace function public.mecca_del(p_login text, p_pass text, p_coll text, p_id text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not mecca_check(p_login, p_pass) then raise exception 'mecca: access denied'; end if;
  delete from mecca_docs where coll = p_coll and id = p_id;
end $$;

revoke all on function public.mecca_check(text, text) from public, anon, authenticated;
revoke all on function public.mecca_login(text, text) from public;
revoke all on function public.mecca_put(text, text, text, text, jsonb) from public;
revoke all on function public.mecca_del(text, text, text, text) from public;
grant execute on function public.mecca_login(text, text) to anon, authenticated;
grant execute on function public.mecca_put(text, text, text, text, jsonb) to anon, authenticated;
grant execute on function public.mecca_del(text, text, text, text) to anon, authenticated;

-- изменения в реальном времени
do $$ begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'mecca_docs') then
    alter publication supabase_realtime add table public.mecca_docs;
  end if;
end $$;

